/// <summary>
///
/// </summary>
public static void CreateOrUpdateParameter(ClassName _className, MethodName _methodName, anytype _value)
{
    TFMDocumentParameters   docParm;
    ttsbegin;
    select firstonly forupdate docParm where docParm.ClassName == _className && docParm.MethodName == _methodName;

    docParm.MethodName  = _methodName;
    docParm.Value       = [_value];
    docParm.ClassName   = _className;
    docParm.ValueString = strFmt('%1', _value);
    docParm.write();
    ttscommit;
}

public static boolean exists(ClassName _className, MethodName _methodName)
{
    TFMDocumentParameters   docParm;
    select firstonly RecId from docParm where docParm.ClassName == _className && docParm.MethodName == _methodName;
    return docParm.RecId != 0;
}

public static anytype getValue(ClassName _className, MethodName _methodName)
{
    TFMDocumentParameters   docParm;    
    SysDictClass            DC;
    DictMethod              dm;    
    Array                   array;
    int                     j;
    anytype                 retVal;
    TFMParameterAttribute   parmAttr;
    select firstonly forupdate docParm where docParm.ClassName == _className && docParm.MethodName == _methodName;

    if (docParm.RecId)
    {
        return conPeek(docParm.Value,1);
    }
    dm = new DictMethod(UtilElementType::ClassInstanceMethod, className2Id(_className), _methodName);

    array = DM.getAttributes(classstr(TFMParameterAttribute));
    if (array != null)
    {
        for (j = 1; j <= array.lastIndex(); j++)
        {
            parmAttr = array.value(j);

            retVal = parmAttr.parmDefaultValue();
        }
    }

    return retVal;
}
